import itertools
import random
import re

LETTERS = "ABCDE"
SMALL_CASES = (
    (100, 100, 100, 100, 100),
    (2718, 2718, 2718, 2718, 2718),
    (100, 100, 100, 200, 300),
    (100, 200, 400, 800, 1600),
    (100, 101, 2716, 2717, 2718),
    (400, 500, 600, 700, 800),
    (800, 800, 900, 900, 1000),
    (100, 100, 100, 100, 2718),
)


def _parse_scores(inp: str) -> tuple[int, ...] | None:
    tokens = inp.split()
    if len(tokens) != 5:
        return None

    scores = []
    for token in tokens:
        if re.fullmatch(r"\+?[0-9]+", token) is None:
            return None
        digits = token.lstrip("+").lstrip("0")
        if not 3 <= len(digits) <= 4:
            return None
        value = int(digits)
        if not 100 <= value <= 2718:
            return None
        if scores and value < scores[-1]:
            return None
        scores.append(value)
    return tuple(scores)


def _format_input(scores: tuple[int, ...] | list[int]) -> str:
    return " ".join(map(str, scores)) + "\n"


def validate_input(inp: str) -> bool:
    return _parse_scores(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    cases = []
    for index in range(n):
        if index < len(SMALL_CASES):
            scores = SMALL_CASES[index]
        elif index % 2 == 0:
            step = rng.randint(100, 900)
            scores = sorted(step * rng.randint(1, 3) for _ in LETTERS)
        else:
            scores = sorted(rng.randint(100, 2718) for _ in LETTERS)
        cases.append(_format_input(scores))
    return cases


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    gap = rng.randint(100, 108)
    return [
        _format_input((2718, 2718, 2718, 2718, 2718)),
        _format_input((gap, gap, 2 * gap, 2718 - gap, 2718)),
    ]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    scores = _parse_scores(inp)
    if scores is None:
        return [("POST-1", "The input does not satisfy the score preconditions.")]

    normalized = out.replace("\r\n", "\n")
    names = normalized.removesuffix("\n").split("\n")
    if len(names) != 31:
        return [("POST-2", f"Expected 31 lines, found {len(names)}.")]

    for line_number, name in enumerate(names, start=1):
        if not name or re.fullmatch(r"A?B?C?D?E?", name) is None:
            return [("POST-2", f"Invalid participant name on line {line_number}.")]

    failures = []
    if len(set(names)) != 31:
        failures.append(("POST-3", "At least one participant appears more than once."))

    points = dict(zip(LETTERS, scores))
    totals = [sum(points[letter] for letter in name) for name in names]
    for index in range(1, len(names)):
        if totals[index - 1] < totals[index]:
            failures.append(
                ("POST-4", f"The score increases between lines {index} and {index + 1}.")
            )
        elif totals[index - 1] == totals[index] and names[index - 1] > names[index]:
            failures.append(
                ("POST-5", f"Tied names are out of order on lines {index} and {index + 1}.")
            )
    return failures


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = []
    for index in range(n):
        factor = rng.randint(2, 27)
        upper = 2718 // factor
        if index % 2 == 0:
            value = rng.randint(100, upper)
            scores = [value] * 5
        else:
            scores = sorted(rng.randint(100, upper) for _ in LETTERS)
        scaled = [value * factor for value in scores]
        pairs.append(("POST-6", "equal", _format_input(scores), _format_input(scaled)))
    return pairs


def reference_small(inp: str) -> str | None:
    scores = _parse_scores(inp)
    if scores is None:
        return None

    points = dict(zip(LETTERS, scores))
    participants = []
    for length in range(1, len(LETTERS) + 1):
        for letters in itertools.combinations(LETTERS, length):
            participants.append(("".join(letters), sum(points[letter] for letter in letters)))

    by_rank = [""] * len(participants)
    for name, score in participants:
        preceding = sum(
            other_score > score or (other_score == score and other_name < name)
            for other_name, other_score in participants
        )
        by_rank[preceding] = name
    return "\n".join(by_rank) + "\n"
